const today = $now.toFormat('yyyy-MM-dd');
const due = [];

for (const item of $input.all()) {
  const lead = item.json;
  const status = String(lead.status || 'active').trim().toLowerCase();
  const dueDate = String(lead.next_follow_up || '').trim();
  const lastSent = String(lead.last_sent || '').trim();
  const email = String(lead.email || '').trim();

  if (status !== 'active' || !email || !dueDate) continue;
  if (dueDate > today || lastSent === today) continue;

  const name = String(lead.name || 'there').trim();
  const interest = String(lead.interest || 'your enquiry').trim();
  const subject = String(lead.subject || ('Quick follow-up: ' + interest)).trim();
  const body = String(lead.body || ('Hi ' + name + ',\n\nJust following up on ' + interest + '. Is this still a priority for you?\n\nBest,\nYOUR_NAME'));

  due.push({json: {lead_id: lead.lead_id, name, email, interest, status, next_follow_up: dueDate, last_sent: lastSent, subject, body}});
}

return due;
